            vfloat32m1_t v_qq_old = __riscv_v_load_i32m1_f32(&apps_qq_old[i]);
            vfloat32m1_t v_q_new_else = __riscv_v_add_vv_f32(__riscv_v_mul_vv_f32(v_ssc_sqrt, v_ql_old), v_qq_old);

            vfloat32m1_t v_q_new = __riscv_v_blend_vv_f32(v_q_new_else, v_zero, v_mask);
            __riscv_v_store_i32m1_f32(&apps_q_new[i], v_q_new);
            i += vl;
        }

        // Loop 3: apps_e_new[i] += 0.5f * apps_delvc[i] * (3.0f*(apps_p_old[i] + apps_q_old[i]) - 4.0f*(apps_pHalfStep[i] + apps_q_new[i]))
        for (Index_type i = 0; i < APPS_N1D; ) {
            size_t vl = __riscv_vsetvlmax_e32m8();
            vfloat32m1_t v_e_new = __riscv_v_load_i32m1_f32(&apps_e_new[i]);
            vfloat32m1_t v_delvc = __riscv_v_load_i32m1_f32(&apps_delvc[i]);
            vfloat32m1_t v_p_old = __riscv_v_load_i32m1_f32(&apps_p_old[i]);
            vfloat32m1_t v_q_old = __riscv_v_load_i32m1_f32(&apps_q_old[i]);
            vfloat32m1_t v_pHalf = __riscv_v_load_i32m1_f32(&apps_pHalfStep[i]);
            vfloat32m1_t v_q_new = __riscv_v_load_i32m1_f32(&apps_q_new[i]);

            vfloat32m1_t v_sum_pq = __riscv_v_add_vv_f32(v_p_old, v_q_old);
            vfloat32m1_t v_term1 = __riscv_v_mul_vf_f32(v_sum_pq, 3.0f);
            vfloat32m1_t v_sum_pHalf_qnew = __riscv_v_add_vv_f32(v_pHalf, v_q_new);
            vfloat32m1_t v_term2 = __riscv_v_mul_vf_f32(v_sum_pHalf_qnew, 4.0f);

            vfloat32m1_t v_diff = __riscv_v_sub_vv_f32(v_term1, v_term2);
            vfloat32m1_t v_update = __riscv_v_mul_vf_f32(__riscv_v_mul_vv_f32(v_delvc, v_diff), half);
            vfloat32m1_t v_e_new_updated = __riscv_v_add_vv_f32(v_e_new, v_update);

            __riscv_v_store_i32m1_f32(&apps_e_new[i], v_e_new_updated);
            i += vl;
        }

        // Loop 4: apps_e_new[i] += 0.5f * apps_work[i]; if (ABS(apps_e_new[i]) < e_cut) apps_e_new[i] = 0.0f; if (apps_e_new[i] < emin) apps_e_new[i] = emin;
        for (Index_type i = 0; i < APPS_N1D; ) {
            size_t vl = __riscv_vsetvlmax_e32m8();
            vfloat32m1_t v_e_new = __riscv_v_load_i32m1_f32(&apps_e_new[i]);
            vfloat32m1_t v_work = __riscv_v_load_i32m1_f32(&apps_work[i]);

            vfloat32m1_t v_e_new_plus_work = __riscv_v_add_vv_f32(v_e_new, __riscv_v_mul_vf_f32(v_work, half));

            vfloat32m1_t v_abs = __riscv_v_abs_vf_f32(v_e_new_plus_work);
            vfloat32m1_t v_mask_cut = __riscv_v_lt_vf_f32(v_abs, __riscv_v_splat_f32(e_cut));
            vfloat32m1_t v_e_clamped_cut = __riscv_v_blend_vv_f32(__riscv_v_splat_f32(0.0f), v_e_new_plus_work, v_mask_cut);

            vfloat32m1_t v_mask_emin = __riscv_v_lt_vf_f32(v_e_clamped_cut, __riscv_v_splat_f32(emin));
            vfloat32m1_t v_final_e = __riscv_v_blend_vv_f32(__riscv_v_splat_f32(emin), v_e_clamped_cut, v_mask_emin);

            __riscv_v_store_i32m1_f32(&apps_e_new[i], v_final_e);
            i += vl;
        }
        dummy(apps_e_new, apps_q_new, NULL, NULL, NULL, e_cut);
    }
    #else
    for (int nl = 0; nl < iterations / 8 + 1; nl++) {
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_e_new[i] = apps_e_old[i] - 0.5f * apps_delvc[i] *
                            (apps_p_old[i] + apps_q_old[i]) + 0.5f * apps_work[i];
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            if (apps_delvc[i] > 0.0f) {
                apps_q_new[i] = 0.0f;
            } else {
                real_t vhalf = 1.0f / (1.0f + apps_compHalfStep[i]);
                real_t ssc = ( apps_pbvc[i] * apps_e_new[i] +
                               vhalf * vhalf * apps_bvc[i] * apps_pHalfStep[i] ) / rho0;
                if (ssc <= 1.111111e-36f) ssc = 3.333333e-18f;
                else                      ssc = sqrtf(ssc);
                apps_q_new[i] = ssc * apps_ql_old[i] + apps_qq_old[i];
            }
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_e_new[i] += 0.5f * apps_delvc[i] *
                             ( 3.0f*(apps_p_old[i] + apps_q_old[i]) -
                               4.0f*(apps_pHalfStep[i] + apps_q_new[i]) );
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_e_new[i] += 0.5f * apps_work[i];
            if (ABS(apps_e_new[i]) < e_cut) apps_e_new[i] = 0.0f;
            if (apps_e_new[i] < emin)        apps_e_new[i] = emin;
        }
        dummy(apps_e_new, apps_q_new, NULL, NULL, NULL, e_cut);
    }
    #endif

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

