real_t apps_ltimes_noview(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type num_d = LTIMES_NUM_D, num_m = LTIMES_NUM_M;
    Index_type num_g = LTIMES_NUM_G, num_z = LTIMES_NUM_Z;

    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type z = 0; z < num_z; ++z) {
            for (Index_type g = 0; g < num_g; ++g) {
                Index_type base_m = g * num_m + z * num_m * num_g;
                Index_type base_g = g * num_d + z * num_d * num_g;

                for (Index_type m = 0; m < num_m; ++m) {
                    Index_type current_m_idx = base_m + m;

                    #if defined(__riscv_vector)
                    float sum_val = 0.0f;
                    float* elldat_ptr = &lt_elldat[m * num_d];
                    float* psidat_ptr = &lt_psidat[base_g];

                    size_t vl;
                    // Use standard RVV intrinsics for loading and multiplying
                    // We use a loop to handle the dot product accumulation
                    for (size_t i = 0; i < num_d; ) {
                        vl = __riscv_vsetvl_e32m1(num_d - i);
                        vfloat32m1_t v_e = __riscv_vle32_v_f32m1(elldat_ptr + i, vl);
                        vfloat32m1_t v_p = __riscv_vle32_v_f32m1(psidat_ptr + i, vl);
                        vfloat32m1_t v_prod = __riscv_vfmul_vv_f32m1(v_e, v_p, vl);

                        // Accumulate into sum_val using a reduction-like approach
                        // Since we need to sum all elements in v_prod
                        for (size_t j = 0; j < vl; ++j) {
                            sum_val += __riscv_v_index_f32m1(v_prod, j);
                        }
                        i += vl;
                    }

                    lt_phidat[current_m_idx] += sum_val;
                    #else
                    for (Index_type dd = 0; dd < num_d; ++dd) {
                        lt_phidat[current_m_idx] += lt_elldat[dd + m * num_d] * lt_psidat[dd + base_g];
                    }
                    #endif
                }
            }
        }
        dummy(lt_phidat, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

