real_t apps_nodal_accumulation_3d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    int nl_limit = iterations / 4 + 1;

    for (int nl = 0; nl < nl_limit; nl++) {
        #if defined(__riscv_vector)
        for (Index_type i = 0; i < APPS_N1D; ) {
            size_t current_vl = __riscv_vsetvl_e32m1(APPS_N1D - i);

            // Load apps_vol[i]
            vfloat32m1_t v_vol = __riscv_vle32_v_f32m1(apps_vol + i, current_vl);

            // Multiply by 0.125f
            vfloat32m1_t v_val = __riscv_vfmul_vf_f32m1(v_vol, 0.125f, current_vl);

            // Store to all 8 arrays
            // The compiler error suggests that the intrinsic __riscv_vse32_v_f32m1 
            // expects a specific vector type or pointer type. 
            // We use the standard vector store intrinsic.
            __riscv_vse32_v_f32m1(v_val, (float*)(apps_x0 + i), current_vl);
            __riscv_vse32_v_f32m1(v_val, (float*)(apps_x1 + i), current_vl);
            __riscv_vse32_v_f32m1(v_val, (float*)(apps_x2 + i), current_vl);
            __riscv_vse32_v_f32m1(v_val, (float*)(apps_x3 + i), current_vl);
            __riscv_vse32_v_f32m1(v_val, (float*)(apps_x4 + i), current_vl);
            __riscv_vse32_v_f32m1(v_val, (float*)(apps_x5 + i), current_vl);
