real_t apps_pressure(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t cls = 1.0f, p_cut = 1.0e-7f, pmin = 0.0f, eosvmax = 1.0e9f;
    int nl_limit = iterations / 4 + 1;

    for (int nl = 0; nl < nl_limit; nl++) {
        #if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t v_cls = __riscv_vfmv_f_s_f32m1_f32((float)cls);
        vfloat32m1_t v_one = __riscv_vfmv_f_s_f32m1_f32((float)1.0f);

        for (Index_type i = 0; i < APPS_N1D; i += vl) {
            vl = __riscv_v_ck_set_vl_f32m1(APPS_N1D - i, vl);
            vfloat32m1_t v_comp = __riscv_v_lmul_vs_f32m1_f32(&apps_compression[i], vl);
            vfloat32m1_t v_sum = __riscv_v_fmadd_f32_f32m1(v_comp, v_one, v_cls, vl);
            __riscv_v_fsdot_f32m1_f32(&apps_bvc[i], v_sum, vl);
        }

        vfloat32m1_t v_p_cut = __riscv_vfmv_f_s_f32m1_f32((float)p_cut);
        vfloat32m1_t v_pmin = __riscv_vfmv_f_s_f32m1_f32((float)pmin);
        vfloat32m1_t v_eosvmax = __riscv_vfmv_f_s_f32m1_f32((float)eosvmax);
        vfloat32m1_t v_zero = __riscv_vfmv_f_s_f32m1_f32((float)0.0f);

        for (Index_type i = 0; i < APPS_N1D; i += vl) {
            vl = __riscv_v_ck_set_vl_f32m1(APPS_N1D - i, vl);
            vfloat32m1_t v_bvc = __riscv_v_lmul_vs_f32m1_f32(&apps_bvc[i], vl);
            vfloat32m1_t v_e_old = __riscv_v_lmul_vs_f32m1_f32(&apps_e_old[i], vl);
            vfloat32m1_t v_p = __riscv_v_fmmul_f32_f32m1(v_bvc, v_e_old, vl);

            // if (ABS(p) < p_cut) p = 0.0f;
            vfloat32m1_t v_abs_p = __riscv_v_vabs_f32_f32m1(v_p, vl);
            vfloat32m1_t v_mask1 = __riscv_v_v_cmp_lt_f32_f32m1(v_abs_p, v_p_cut, vl);
            v_p = __riscv_v_v_blend_f32m1(v_p, v_zero, v_mask1, vl);

            // if (apps_vnewc[i] >= eosvmax) p = 0.0f;
            vfloat32m1_t v_vnewc = __riscv_v_lmul_vs_f32m1_f32(&apps_vnewc[i], vl);
            vfloat32m1_t v_mask2 = __riscv_v_v_cmp_ge_f32_f32m1(v_vnewc, v_eosvmax, vl);
            v_p = __riscv_v_v_blend_f32m1(v_p, v_zero, v_mask2, vl);

            // if (p < pmin) p = pmin;
            vfloat32m1_t v_mask3 = __riscv_v_v_cmp_lt_f32_f32m1(v_p, v_pmin, vl);
            v_p = __riscv_v_v_blend_f32m1(v_p, v_pmin, v_mask3, vl);

            __riscv_v_fsdot_f32m1_f32(&apps_p_new[i], v_p, vl);
        }
        #else
        // Scalar fallback
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_bvc[i] = cls * (apps_compression[i] + 1.0f);
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t p = apps_bvc[i] * apps_e_old[i];
            if (ABS(p) < p_cut)         p = 0.0f;
            if (apps_vnewc[i] >= eosvmax) p = 0.0f;
            if (p < pmin)               p = pmin;
            apps_p_new[i] = p;
        }
        #endif
        dummy(apps_p_new, apps_bvc, NULL, NULL, NULL, p_cut);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

