        for (Index_type i = 0; i < APPS_N1D; ) {
            size_t vl = __riscv_vsetvl_e32m1(APPS_N1D - i);

            vfloat32m1_t v0 = __riscv_vle32_v_f32m1(apps_x0 + i, vl);
            vfloat32m1_t v1 = __riscv_vle32_v_f32m1(apps_x1 + i, vl);
            vfloat32m1_t v2 = __riscv_vle32_v_f32m1(apps_x2 + i, vl);
            vfloat32m1_t v3 = __riscv_vle32_v_f32m1(apps_x3 + i, vl);
            vfloat32m1_t v4 = __riscv_vle32_v_f32m1(apps_x4 + i, vl);
