            sum = __riscv_vfmacc_vv(sum, v4, vl);
            sum = __riscv_vfmacc_vv(sum, v5, vl);
            sum = __riscv_vfmacc_vv(sum, v6, vl);
            sum = __riscv_vfmacc_vv(sum, v7, vl);

            vfloat32m1_t factor = __riscv_vf_v_f32m1(0.125f, vl);
            vfloat32m1_t result = __riscv_vfmul_vv(sum, factor, vl);

            __riscv_vse32_v_f32m1(apps_vol + i, result, vl);
            i += vl;
