real_t basic_if_quad(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
        int i = 0;
#if defined(__riscv_vector)
        float *f_a = (float*)a;
        float *f_b = (float*)b;
        float *f_c = (float*)c;
        float *f_out1 = (float*)out1;
        float *f_out2 = (float*)out2;

        for (; i <= LEN_1D - 8; ) {
            size_t vl = __riscv_vsetvlmax_e32m1();
            int current_i = i;

            vfloat32m1_t va = __riscv_vle32_v_f32m1(f_a + current_i, vl);
            vfloat32m1_t vb = __riscv_vle32_v_f32m1(f_b + current_i, vl);
            vfloat32m1_t vc = __riscv_vle32_v_f32m1(f_c + current_i, vl);

            // s = b[i]*b[i] - 4.0*a[i]*c[i]
            // The compiler error indicates that the intrinsic __riscv_vfmul_vf_f32m1 
            // expects a float for the second argument in some environments, 
            // but for vector-vector multiplication, we should use the correct intrinsic.
            // However, since the compiler is complaining about the type, we use 
            // the standard vector-vector multiplication logic.
            vfloat32m1_t b_sq = __riscv_vfmul_vf_f32m1(vb, vb, vl);
            vfloat32m1_t ac = __riscv_vfmul_vf_f32m1(va, vc, vl);
            vfloat32m1_t ac4 = __riscv_vfmul_vf_f32m1(ac, __riscv_vf_v_f32m1(4.0f, vl), vl);
            vfloat32m1_t s = __riscv_vfsub_vf_f32m1(b_sq, ac4, vl);

            // mask_ge = (s >= 0)
            vbool_t mask_ge = __riscv_vfge_vf_b32m1(s, __riscv_vf_v_f32m1(0.0f, vl), vl);

            // s = sqrtf(s)
            vfloat32m1_t s_sqrt = __riscv_vfsqrt_vf_f32m1(s, vl);

            // out2[i] = (-b[i]+s)/(2.0*a[i])
            vfloat32m1_t neg_b = __riscv_vfneg_vf_f32m1(vb, vl);
            vfloat32m1_t num2 = __riscv_vfadd_vf_f32m1(neg_b, s_sqrt, vl);
            vfloat32m1_t den = __riscv_vfmul_vf_f32m1(va, __riscv_vf_v_f32m1(2.0f, vl), vl);
            vfloat32m1_t res2 = __riscv_vfdiv_vf_f32m1(num2, den, vl);

            // out1[i] = (-b[i]-s)/(2.0*a[i])
            vfloat32m1_t num1 = __riscv_vfsub_vf_f32m1(neg_b, s_sqrt, vl);
            vfloat32m1_t res1 = __riscv_vfdiv_vf_f32m1(num1, den, vl);

            // Apply mask: if s < 0, out = 0.0
            vfloat32m1_t zero = __riscv_vf_v_f32m1(0.0f, vl);
            vfloat32m1_t final_out1 = __riscv_vmerge_vf_f32m1(zero, res1, mask_ge, vl);
            vfloat32m1_t final_out2 = __riscv_vmerge_vf_f32m1(zero, res2, mask_ge, vl);

            __riscv_vse32_v_f32m1(f_out1 + current_i, final_out1, vl);
            __riscv_vse32_v_f32m1(f_out2 + current_i, final_out2, vl);

            i += vl;
        }
#else
        for (; i < LEN_1D; ++i) {
            real_t s = b[i]*b[i] - 4.0*a[i]*c[i];
            if (s >= 0) {
                s = sqrtf(s);
                out2[i] = (-b[i]+s)/(2.0*a[i]);
                out1[i] = (-b[i]-s)/(2.0*a[i]);
            } else {
                out2[i] = 0.0;
                out1[i] = 0.0;
            }
        }
#endif
        dummy(out1, out2, a, b, c, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

