real_t basic_indexlist_3loop(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type len = 0;
    int outer_limit = iterations / 8 + 1;

    for (int nl = 0; nl < outer_limit; nl++) {
        // Loop 1: idx_counts[i] = (x[i] < 0.0) ? 1 : 0;
        #if defined(__riscv_vector)
        for (Index_type i = 0; i < LEN_1D; ) {
            size_t vl = __riscv_vsetvlmax_e32m1();
            if (i + vl > LEN_1D) vl = LEN_1D - i;

            vfloat32m1_t vx = __riscv_vle32_v_f32m1(x + i, vl);
            vfloat32m1_t vcond = __riscv_vf_vmslt_vx_f32m1(vx, 0.0f);

            // Use vmerge to select 1.0f or 0.0f based on the condition
            vfloat32m1_t vzero = __riscv_vvm_v_f32m1(vcond, vcond, 0.0f);
            vfloat32m1_t vone = __riscv_vvm_v_f32m1(vcond, vcond, 1.0f);
            vfloat32m1_t vres = __riscv_vmerge_v_f32m1(vzero, vone, vcond);

            __riscv_vse32_v_f32m1(vres, idx_counts + i, vl);
            i += vl;
        }
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            idx_counts[i] = (x[i] < 0.0) ? 1 : 0;
        }
        #endif

        Index_type count = 0;
        // Loop 2: Prefix sum / Shift logic
        // This loop is inherently sequential because idx_counts[i] depends on the previous count
        for (Index_type i = 0; i <= LEN_1D; ++i) {
            Index_type inc = idx_counts[i];
            idx_counts[i] = count;
            count += inc;
        }

        // Loop 3: idx_list[idx_counts[i]] = i;
        for (Index_type i = 0; i < LEN_1D; ++i) {
            if (idx_counts[i] != idx_counts[i+1]) {
                idx_list[idx_counts[i]] = i;
            }
        }

        len = idx_counts[LEN_1D];
        dummy(NULL, NULL, NULL, NULL, NULL, (real_t)count);
    }
    idx_list[0] = len;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

