real_t basic_pi_atomic(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t dx = 1.0 / (real_t)LEN_1D;
    real_t pi_acc = 0.0;

    for (int nl = 0; nl < iterations; nl++) {
        real_t pi = 0.0;

        #if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t v_dx = __riscv_v_fmv_xz_f32((float)dx);
        vfloat32m1_t v_one = __riscv_v_fmv_xz_f32(1.0f);
        vfloat32m1_t v_half = __riscv_v_fmv_xz_f32(0.5f);

        vfloat32m1_t v_sum = __riscv_v_vmv_v_f32m1(v_dx, 0); 

        for (Index_type i = 0; i < LEN_1D; i += vl) {
            vl = __riscv_v_vi_m1(i, LEN_1D);
            vfloat32m1_t v_i = __riscv_v_vi_m1(i, vl);

            // xv = (i + 0.5) * dx
            vfloat32m1_t v_xv = __riscv_v_fmadd_f32(v_i, v_half, v_dx, vl);

            // xv * xv
            vfloat32m1_t v_xv2 = __riscv_v_fmadd_f32(v_xv, v_xv, v_one, vl);

            // term = dx / (1.0 + xv * xv)
            vfloat32m1_t v_denom = __riscv_v_vfadd_f32(v_one, v_xv2, vl);
            vfloat32m1_t v_term = __riscv_v_vfdiv_f32(v_dx, v_denom, vl);

            // pi += term
            v_sum = __riscv_v_vfadd_f32(v_sum, v_term, vl);
        }
        pi = __riscv_v_fredu_f32m1(v_sum, vl);
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t xv = ((real_t)i + 0.5) * dx;
            pi += dx / (1.0 + xv * xv);
        }
        #endif

        pi_acc += pi * 4.0;
        dummy(NULL, NULL, NULL, NULL, NULL, pi);
    }
    x[0] = pi_acc / (real_t)iterations;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

