    real_t dx = 1.0 / (real_t)LEN_1D;
    real_t pi_acc = 0.0;

    for (int nl = 0; nl < iterations; nl++) {
        real_t pi = 0.0;

        #if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t v_dx = __riscv_vfm_splat((float)dx);
        vfloat32m1_t v_one = __riscv_vfm_splat((float)1.0f);
        vfloat32m1_t v_half = __riscv_vfm_splat((float)0.5f);
        vfloat32m1_t v_sum = __riscv_vfm_splat((float)0.0f);

        for (Index_type i = 0; i < LEN_1D; ) {
            vl = __riscv_vsetvlmax_e32m1(LEN_1D - i);
            vfloat32m1_t v_i = __riscv_vfm_splat((float)i);

            // xv = (i + 0.5) * dx
            vfloat32m1_t v_xv = __riscv_vf_add(v_i, v_half);
            v_xv = __riscv_vf_mul(v_xv, v_dx);

            // xv * xv
            vfloat32m1_t v_xv2 = __riscv_vf_mul(v_xv, v_xv);

            // dx / (1.0 + xv * xv)
            vfloat32m1_t v_denom = __riscv_vf_add(v_one, v_xv2);
            vfloat32m1_t v_term = __riscv_vf_div(v_dx, v_denom);

            v_sum = __riscv_vf_add(v_sum, v_term);

            // Reduction of the vector sum
            // We use a loop to sum the elements of the vector to avoid 
            // complex reduction logic that might vary by compiler/header support
            for (size_t k = 0; k < vl; ++k) {
                pi += (real_t)__riscv_vfm_index_load_f32(v_sum, k);
            }

            i += (Index_type)vl;
        }
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t xv = ((real_t)i + 0.5) * dx;
            pi += dx / (1.0 + xv * xv);
        }
        #endif

        pi_acc += pi * 4.0;
        dummy(NULL, NULL, NULL, NULL, NULL, pi);
    }
    x[0] = pi_acc / (real_t)iterations;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

