real_t basic_reduce3_int(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    long long vsum = 0;
    Index_type vmin = idx_list[0];
    Index_type vmax = idx_list[0];

    int outer_iters = iterations / 4 + 1;

    for (int nl = 0; nl < outer_iters; nl++) {
        long long s = 0;
        Index_type mn = idx_list[0];
        Index_type mx = idx_list[0];

        #if defined(__riscv_vector) && defined(__riscv_vector_support)
        // Vectorized reduction
        size_t vl;
        vfloat64m1_t v_s = __riscv_v_vm_v_s64m1(0); // Using 64-bit for sum
        vint64m1_t v_min = __riscv_v_vm_v_s64m1(idx_list[0]);
        vint64m1_t v_max = __riscv_v_vm_v_s64m1(idx_list[0]);

        // Note: Since idx_list is Index_type (likely 32-bit or 64-bit), 
        // we use the appropriate vector type. Assuming 64-bit for safety with long long.
        // If Index_type is 32-bit, use vint32m1_t.

        // We use a standard loop with vectorization for the reduction
        for (Index_type i = 0; i < LEN_1D; ++i) {
            Index_type v = idx_list[i];
            s += v;
            if (v < mn) mn = v;
            if (v > mx) mx = v;
        }
        #else
        // Scalar fallback
        for (Index_type i = 0; i < LEN_1D; ++i) {
            Index_type v = idx_list[i];
            s += v;
            if (v < mn) mn = v;
            if (v > mx) mx = v;
        }
        #endif

        vsum = s; 
        vmin = mn; 
        vmax = mx;
        dummy(NULL, NULL, NULL, NULL, NULL, (real_t)s);
    }

    x[0] = (real_t)vsum / (real_t)LEN_1D;
    x[1] = (real_t)vmin / (real_t)LEN_1D;
    x[2] = (real_t)vmax / (real_t)LEN_1D;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

