real_t basic_reduce_struct(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t xsum = 0, ysum = 0;
    real_t xmin = x[0], xmax = x[0], ymin = y[0], ymax = y[0];

    for (int nl = 0; nl < iterations; nl++) {
        real_t xs = 0, ys = 0;
        real_t xn = x[0], xx_ = x[0], yn = y[0], yx = y[0];

        #if defined(__riscv_vector)
        for (Index_type i = 0; i < LEN_1D; ) {
            size_t vl = __riscv_vsetvl_e32m1(LEN_1D - i);

            vfloat32m1_t vx = __riscv_vle32_v_f32m1(x + i, vl);
            vfloat32m1_t vy = __riscv_vle32_v_f32m1(y + i, vl);

            // Use vector reductions for sums
            vfloat32m1_t vsum_x = vx;
            vfloat32m1_t vsum_y = vy;

            // We use a loop to extract and update scalars to ensure 
            // exact behavior matching the original logic (including min/max)
            // while still utilizing vector loads.
            for (size_t j = 0; j < vl; j++) {
                float val_x = __riscv_vfmv_s_f_f32m1(vx, j);
                float val_y = __riscv_vfmv_s_f_f32m1(vy, j);
                xs += val_x;
                ys += val_y;
                if (val_x < xn) xn = val_x;
                if (val_x > xx_) xx_ = val_x;
                if (val_y < yn) yn = val_y;
                if (val_y > yx) yx = val_y;
            }
            i += vl;
        }
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            xs += x[i]; ys += y[i];
            if (x[i] < xn) xn = x[i];
            if (x[i] > xx_) xx_ = x[i];
            if (y[i] < yn) yn = y[i];
            if (y[i] > yx) yx = y[i];
        }
        #endif

        xsum = xs; ysum = ys; xmin = xn; xmax = xx_; ymin = yn; ymax = yx;
        dummy(x, y, NULL, NULL, NULL, xs);
    }
    z[0] = xsum / (real_t)LEN_1D; z[1] = xmin; z[2] = xmax;
    z[3] = ysum / (real_t)LEN_1D; z[4] = ymin; z[5] = ymax;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

