real_t basic_trap_int(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t x0 = 0.0, h = 1.0 / (real_t)LEN_1D;
    real_t yp = 1.0, ypoint = 1.0;
    real_t acc = 0.0;

    for (int nl = 0; nl < iterations; nl++) {
        real_t sumx = 0.0;

        #if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t v_x0 = __riscv_v_fmv_f32m1_s(x0);
        vfloat32m1_t v_h = __riscv_v_fmv_f32m1_s(h);
        vfloat32m1_t v_one = __riscv_v_fmv_f32m1_s(1.0f);
        vfloat32m1_t v_sumx = __riscv_v_fmv_f32m1_s(0.0f);

        // Precompute (ypoint - yp)^2
        real_t diff_y = ypoint - yp;
        vfloat32m1_t v_diff_y_sq = __riscv_v_fmv_f32m1_s(diff_y * diff_y);

        for (Index_type i = 0; i < LEN_1D; ) {
            vl = __riscv_v_minm_vf32m1(LEN_1D - i, __riscv_v_set_vl_max());

            // Create vector of indices [i, i+1, ..., i+vl-1]
            vint32m1_t v_i = __riscv_v_vmv_v_x_i32m1(__riscv_v_set_i32m1_x(i, vl));

            // xv = x0 + i * h
            vfloat32m1_t v_xv = __riscv_v_fmadd_vf32m1_f32m1(v_h, __riscv_v_vcvt_f32m1_i32m1(v_i), v_x0);

            // (xv - 0.5)
            vfloat32m1_t v_xv_minus_05 = __riscv_v_vfms_vf32m1_f32m1(v_xv, __riscv_v_fmv_f32m1_s(0.5f), __riscv_v_fmv_f32m1_s(1.0f));

            // denom = (xv - 0.5)^2 + (ypoint - yp)^2
            vfloat32m1_t v_denom = __riscv_v_fmadd_vf32m1_f32m1(v_xv_minus_05, v_xv_minus_05, v_diff_y_sq);

            // denom + 1.0
            vfloat32m1_t v_denom_plus_1 = __riscv_v_vfadd_vf32m1(v_denom, v_one);

            // 1.0f / sqrtf(denom + 1.0f)
            vfloat32m1_t v_res = __riscv_v_vfsqrt_vf32m1(v_denom_plus_1);
            vfloat32m1_t v_inv_res = __riscv_v_vfdiv_vf32m1(v_one, v_res);

            v_sumx = __riscv_v_vfadd_vf32m1(v_sumx, v_inv_res);

            i += vl;
        }
        sumx = __riscv_v_fredu_vf32m1(v_sumx);
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t xv = x0 + i*h;
            real_t denom = (xv - 0.5f)*(xv - 0.5f) + (ypoint - yp)*(ypoint - yp);
            sumx += 1.0f / sqrtf(denom + 1.0f);
        }
        #endif

        acc += sumx;
        dummy(NULL, NULL, NULL, NULL, NULL, sumx);
    }
    x[0] = acc / (real_t)(iterations * LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

