real_t lcals_diff_predict(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type offset = LEN_1D;

    for (int nl = 0; nl < iterations; nl++) {
        #if defined(__riscv_vector)
        for (size_t i = 0; i < LEN_1D; ) {
            size_t vl = __riscv_vsetvl_e32m1(LEN_1D - i);

            vfloat32m1_t v_ar = __riscv_vle32_v_f32m1(cx + (i + offset * 4), vl);
            vfloat32m1_t v_px4 = __riscv_vle32_v_f32m1(px + (i + offset * 4), vl);
            vfloat32m1_t v_br = __riscv_vfsub_vv_f32m1(v_ar, v_px4, vl);
            __riscv_vsse32_v_f32m1(px + (i + offset * 4), v_ar, vl);

            vfloat32m1_t v_px5 = __riscv_vle32_v_f32m1(px + (i + offset * 5), vl);
            vfloat32m1_t v_cr = __riscv_vfsub_vv_f32m1(v_br, v_px5, vl);
            __riscv_vsse32_v_f32m1(px + (i + offset * 5), v_br, vl);

            vfloat32m1_t v_px6 = __riscv_vle32_v_f32m1(px + (i + offset * 6), vl);
            vfloat32m1_t v_ar2 = __riscv_vfsub_vv_f32m1(v_cr, v_px6, vl);
            __riscv_vsse32_v_f32m1(px + (i + offset * 6), v_cr, vl);

            vfloat32m1_t v_px7 = __riscv_vle32_v_f32m1(px + (i + offset * 7), vl);
            vfloat32m1_t v_br2 = __riscv_vfsub_vv_f32m1(v_ar2, v_px7, vl);
            __riscv_vsse32_v_f32m1(px + (i + offset * 7), v_ar2, vl);

            vfloat32m1_t v_px8 = __riscv_vle32_v_f32m1(px + (i + offset * 8), vl);
            vfloat32m1_t v_cr2 = __riscv_vfsub_vv_f32m1(v_br2, v_px8, vl);
            __riscv_vsse32_v_f32m1(px + (i + offset * 8), v_br2, vl);

            vfloat32m1_t v_px9 = __riscv_vle32_v_f32m1(px + (i + offset * 9), vl);
            vfloat32m1_t v_ar3 = __riscv_vfsub_vv_f32m1(v_cr2, v_px9, vl);
            __riscv_vsse32_v_f32m1(px + (i + offset * 9), v_cr2, vl);

            vfloat32m1_t v_px10 = __riscv_vle32_v_f32m1(px + (i + offset * 10), vl);
            vfloat32m1_t v_br3 = __riscv_vfsub_vv_f32m1(v_ar3, v_px10, vl);
            __riscv_vsse32_v_f32m1(px + (i + offset * 10), v_ar3, vl);

            vfloat32m1_t v_px11 = __riscv_vle32_v_f32m1(px + (i + offset * 11), vl);
            vfloat32m1_t v_cr3 = __riscv_vfsub_vv_f32m1(v_br3, v_px11, vl);
            __riscv_vsse32_v_f32m1(px + (i + offset * 11), v_br3, vl);

            vfloat32m1_t v_px12 = __riscv_vle32_v_f32m1(px + (i + offset * 12), vl);
            vfloat32m1_t v_res = __riscv_vfsub_vv_f32m1(v_cr3, v_px12, vl);
            __riscv_vsse32_v_f32m1(px + (i + offset * 13), v_res, vl);
            __riscv_vsse32_v_f32m1(px + (i + offset * 12), v_cr3, vl);

            i += vl;
        }
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t ar = cx[i + offset * 4];
            real_t br = ar - px[i + offset * 4];
            px[i + offset * 4]  = ar;
            real_t cr = br - px[i + offset * 5];
            px[i + offset * 5]  = br;
            ar = cr - px[i + offset * 6];  px[i + offset * 6]  = cr;
            br = ar - px[i + offset * 7];  px[i + offset * 7]  = ar;
            cr = br - px[i + offset * 8];  px[i + offset * 8]  = br;
            ar = cr - px[i + offset * 9];  px[i + offset * 9]  = cr;
            br = ar - px[i + offset * 10]; px[i + offset * 10] = ar;
            cr = br - px[i + offset * 11]; px[i + offset * 11] = br;
            px[i + offset * 13] = cr - px[i + offset * 12];
            px[i + offset * 12] = cr;
        }
        #endif
        dummy(cx, px, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

