real_t lcals_eos(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t r = 0.5, t = 0.25, q = 0.125;

    for (int nl = 0; nl < iterations; nl++) {
        int i = 0;
        #if defined(__riscv_vector)
        for (; i <= LEN_1D - 6; ) {
            size_t vl = __riscv_vsetvl_e32m1(LEN_1D - 6 - i);

            vfloat32m1_t v_u0 = __riscv_vle32_v_f32m1(u + i, vl);
            vfloat32m1_t v_u1 = __riscv_vle32_v_f32m1(u + i + 1, vl);
            vfloat32m1_t v_u2 = __riscv_vle32_v_f32m1(u + i + 2, vl);
            vfloat32m1_t v_u3 = __riscv_vle32_v_f32m1(u + i + 3, vl);
            vfloat32m1_t v_u4 = __riscv_vle32_v_f32m1(u + i + 4, vl);
            vfloat32m1_t v_u5 = __riscv_vle32_v_f32m1(u + i + 5, vl);
            vfloat32m1_t v_u6 = __riscv_vle32_v_f32m1(u + i + 6, vl);
            vfloat32m1_t v_y  = __riscv_vle32_v_f32m1(y + i, vl);
            vfloat32m1_t v_z  = __riscv_vle32_v_f32m1(z + i, vl);

            vfloat32m1_t v_r = __riscv_vfmv_v_f_f32m1(r, vl);
            vfloat32m1_t v_t = __riscv_vfmv_v_f_f32m1(t, vl);
            vfloat32m1_t v_q = __riscv_vfmv_v_f_f32m1(q, vl);

            // Part A: r * (z + r * y)
            vfloat32m1_t part_a = __riscv_vfadd_v_f_f32m1(v_z, __riscv_vfmul_v_f_f32m1(v_y, v_r, vl), vl);
            part_a = __riscv_vfmul_v_f_f32m1(part_a, v_r, vl);

            // Part B: t * (u[i+3] + r * (u[i+2] + r * u[i+1]))
            vfloat32m1_t part_b_inner = __riscv_vfadd_v_f_f32m1(v_u2, __riscv_vfmul_v_f_f32m1(v_u1, v_r, vl), vl);
            vfloat32m1_t part_b = __riscv_vfadd_v_f_f32m1(v_u3, __riscv_vfmul_v_f_f32m1(part_b_inner, v_r, vl), vl);
            part_b = __riscv_vfmul_v_f_f32m1(part_b, v_t, vl);

            // Part C: t * (u[i+6] + q * (u[i+5] + q * u[i+4]))
            vfloat32m1_t part_c_inner = __riscv_vfadd_v_f_f32m1(v_u5, __riscv_vfmul_v_f_f32m1(v_u4, v_q, vl), vl);
            vfloat32m1_t part_c = __riscv_vfadd_v_f_f32m1(v_u6, __riscv_vfmul_v_f_f32m1(part_c_inner, v_q, vl), vl);
            part_c = __riscv_vfmul_v_f_f32m1(part_c, v_t, vl);

            vfloat32m1_t v_res = __riscv_vfadd_v_f_f32m1(v_u0, part_a, vl);
            v_res = __riscv_vfadd_v_f_f32m1(v_res, part_b, vl);
            v_res = __riscv_vfadd_v_f_f32m1(v_res, part_c, vl);

            __riscv_vse32_v_f32m1(x + i, v_res, vl);
            i += vl;
        }
        #else
        for (; i < LEN_1D - 6; ++i) {
            x[i] = u[i] + r*( z[i] + r*y[i] ) +
                          t*( u[i+3] + r*( u[i+2] + r*u[i+1] ) +
                             t*( u[i+6] + q*( u[i+5] + q*u[i+4] ) ) );
        }
        #endif
        dummy(x, u, y, z, NULL, q);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

