real_t lcals_first_min(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type loc = 0;
    real_t mn = x[0];

    for (int nl = 0; nl < iterations; nl++) {
        loc = 0;
        mn = x[0];

        #if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t v_min_val = __riscv_vfmv_vf32m1_tu(mn, &vl);

        for (Index_type i = 0; i < LEN_1D; i += vl) {
            vfloat32m1_t v_curr = __riscv_vfmv_vf32m1_tu(x[i], &vl);
            vfloat32m1_t v_res = __riscv_vfmin_vf32m1(v_min_val, v_curr, &vl);
            v_min_val = v_res;

            // To maintain the "first" index logic and handle the 'loc' update,
            // we check if the min changed.
            // We use a scalar check for the index to ensure "first" property 
            // and correct 'loc' update as per original logic.
            for (Index_type j = 0; j < vl && (i + j) < LEN_1D; ++j) {
                if (x[i + j] < mn) {
                    mn = x[i + j];
                    loc = i + j;
                }
            }
            // Update the vector register to reflect the new mn for the next iteration
            v_min_val = __riscv_vfmv_vf32m1_tu(mn, &vl);
        }
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            if (x[i] < mn) {
                mn = x[i];
                loc = i;
            }
        }
        #endif
        dummy(x, NULL, NULL, NULL, NULL, mn);
    }
    y[0] = mn;
    y[1] = (real_t)loc / (real_t)LEN_1D;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

