#endif

real_t lcals_gen_lin_recur(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type kb5i = 0;
    int nl_limit = iterations / 16 + 1;

    for (int nl = 0; nl < nl_limit; nl++) {
        // The first loop processes k from 0 to LEN_1D-1.
        // We use RVV to vectorize this loop.
        #if defined(__riscv_vector)
        for (Index_type k = 0; k < LEN_1D; ) {
            size_t vl;
            vfloat32m1_t v_sa = __riscv_v_vs_firstload_i32m1(sa + k, &vl);
            vfloat32m1_t v_sb = __riscv_v_vs_firstload_i32m1(sb + k, &vl);
            vfloat32m1_t v_stb5 = __riscv_v_vs_firstload_i32m1(stb5 + k, &vl);

            vfloat32m1_t v_prod = __riscv_v_vfmul_vv(v_stb5, v_sb, vl);
            vfloat32m1_t v_b5_res = __riscv_v_vfadd_vv(v_sa, v_prod, vl);

            __riscv_v_vs_firststore_i32m1(b5 + kb5i + k, v_b5_res, &vl);
            vfloat32m1_t v_new_stb5 = __riscv_v_vfsub_vv(v_b5_res, v_stb5, vl);
            __riscv_v_vs_firststore_i32m1(stb5 + k, v_new_stb5, &vl);

            k += vl;
        }
        #else
        for (Index_type k = 0; k < LEN_1D; ++k) {
            b5[k+kb5i] = sa[k] + stb5[k]*sb[k];
            stb5[k] = b5[k+kb5i] - stb5[k];
        }
        #endif

        // The second loop processes k from LEN_1D-1 down to 0.
        // This loop is inherently sequential due to the dependency on the 
        // updated values of b5 and stb5 from the previous iteration of k.
        for (Index_type i = 1; i < LEN_1D + 1; ++i) {
            Index_type k = LEN_1D - i;
            b5[k+kb5i] = sa[k] + stb5[k]*sb[k];
            stb5[k] = b5[k+kb5i] - stb5[k];
        }

        dummy(b5, stb5, sa, sb, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_hydro_1d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t q = 0.5, r = 0.25, t = 0.125;

    #if defined(__riscv_vector)
    for (int nl = 0; nl < iterations; nl++) {
        size_t n = LEN_1D - 12;

        for (size_t i = 0; i < n; ) {
            size_t vl = __riscv_v_vsetvl_e32m1(n - i);

            vfloat32m1_t v_q = __riscv_v_fmv_f_s_f32m1_f32(q, vl);
            vfloat32m1_t v_r = __riscv_v_fmv_f_s_f32m1_f32(r, vl);
            vfloat32m1_t v_t = __riscv_v_fmv_f_s_f32m1_f32(t, vl);

            vfloat32m1_t v_y = __riscv_v_vle32_v_f32m1(y + i, vl);
            vfloat32m1_t v_z10 = __riscv_v_vle32_v_f32m1(z + i + 10, vl);
            vfloat32m1_t v_z11 = __riscv_v_vle32_v_f32m1(z + i + 11, vl);

            // term = r*z[i+10] + t*z[i+11]
            vfloat32m1_t v_term1 = __riscv_v_vfmul_vv_f32m1(v_r, v_z10, vl);
            vfloat32m1_t v_term2 = __riscv_v_vfmul_vv_f32m1(v_t, v_z11, vl);
            vfloat32m1_t v_term = __riscv_v_vfadd_vv_f32m1(v_term1, v_term2, vl);

            // x[i] = q + y[i] * term
            vfloat32m1_t v_prod = __riscv_v_vfmul_vv_f32m1(v_y, v_term, vl);
            vfloat32m1_t v_res = __riscv_v_vfadd_vv_f32m1(v_q, v_prod, vl);

            __riscv_v_vse32_v_f32m1(x + i, v_res, vl);
            i += vl;
        }
        dummy(x, y, z, NULL, NULL, q);
    }
    #else
    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type i = 0; i < LEN_1D - 12; ++i) {
            x[i] = q + y[i]*( r*z[i+10] + t*z[i+11] );
        }
        dummy(x, y, z, NULL, NULL, q);
    }
    #endif

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_hydro_2d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t s = 0.0001, t = 0.5;
    Index_type kn = LEN_2D, jn = LEN_2D;

    for (int nl = 0; nl < iterations / 32 + 1; nl++) {
        // First loop: Compute za and zb
        for (Index_type k = 1; k < kn - 1; ++k) {
            Index_type j = 1;
            #if defined(__riscv_vector)
            size_t vlen_max = __riscv_vector.maximum_vector_length;
            for (; j <= jn - 1 - (Index_type)vlen_max; j += (Index_type)vlen_max) {
                size_t vl = vlen_max;
                vfloat32m1_t v_zp_k1_jm1 = __riscv_vector.vle32_v(zp[k+1] + (j-1) * sizeof(real_t), vl);
                vfloat32m1_t v_zq_k1_jm1 = __riscv_vector.vle32_v(zq[k+1] + (j-1) * sizeof(real_t), vl);
                vfloat32m1_t v_zp_k_jm1  = __riscv_vector.vle32_v(zp[k] + (j-1) * sizeof(real_t), vl);
                vfloat32m1_t v_zq_k_jm1  = __riscv_vector.vle32_v(zq[k] + (j-1) * sizeof(real_t), vl);

                vfloat32m1_t v_zr_k_j    = __riscv_vector.vle32_v(zr[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zr_k_jm1  = __riscv_vector.vle32_v(zr[k] + (j-1) * sizeof(real_t), vl);
                vfloat32m1_t v_zm_k_jm1  = __riscv_vector.vle32_v(zm[k] + (j-1) * sizeof(real_t), vl);
                vfloat32m1_t v_zm_k1_jm1 = __riscv_vector.vle32_v(zm[k+1] + (j-1) * sizeof(real_t), vl);

                vfloat32m1_t v_term1 = __riscv_vector.vfadd_vv(v_zp_k1_jm1, v_zq_k1_jm1);
                vfloat32m1_t v_term2 = __riscv_vector.vfsub_vv(v_term1, v_zp_k_jm1);
                vfloat32m1_t v_term3 = __riscv_vector.vfsub_vv(v_term2, v_zq_k_jm1);

                vfloat32m1_t v_zr_sum = __riscv_vector.vfadd_vv(v_zr_k_j, v_zr_k_jm1);
                vfloat32m1_t v_zm_sum = __riscv_vector.vfadd_vv(v_zm_k_jm1, v_zm_k1_jm1);

                vfloat32m1_t v_za_final = __riscv_vector.vfmul_vv(v_term3, v_zr_sum);
                vfloat32m1_t v_za_res = __riscv_vector.vfdiv_vv(v_za_final, v_zm_sum);
                __riscv_vector.vse32_v(v_za_res, za[k] + j * sizeof(real_t), vl);

                vfloat32m1_t v_zp_k_j_m1 = __riscv_vector.vle32_v(zp[k] + (j-1) * sizeof(real_t), vl);
                vfloat32m1_t v_zq_k_j_m1 = __riscv_vector.vle32_v(zq[k] + (j-1) * sizeof(real_t), vl);
                vfloat32m1_t v_zp_k_j    = __riscv_vector.vle32_v(zp[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zq_k_j    = __riscv_vector.vle32_v(zq[k] + j * sizeof(real_t), vl);

                vfloat32m1_t v_zr_k_j_k1 = __riscv_vector.vle32_v(zr[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zr_k1_j   = __riscv_vector.vle32_v(zr[k-1] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zm_k_j    = __riscv_vector.vle32_v(zm[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zm_k_jm1  = __riscv_vector.vle32_v(zm[k] + (j-1) * sizeof(real_t), vl);

                vfloat32m1_t v_zb_term1 = __riscv_vector.vfadd_vv(v_zp_k_j_m1, v_zq_k_j_m1);
                vfloat32m1_t v_zb_term2 = __riscv_vector.vfsub_vv(v_zb_term1, v_zp_k_j);
                vfloat32m1_t v_zb_term3 = __riscv_vector.vfsub_vv(v_zb_term2, v_zq_k_j);

                vfloat32m1_t v_zr_zb_sum = __riscv_vector.vfadd_vv(v_zr_k_j_k1, v_zr_k1_j);
                vfloat32m1_t v_zm_zb_sum = __riscv_vector.vfadd_vv(v_zm_k_j, v_zm_k_jm1);

                vfloat32m1_t v_zb_final = __riscv_vector.vfmul_vv(v_zb_term3, v_zr_zb_sum);
                vfloat32m1_t v_zb_res = __riscv_vector.vfdiv_vv(v_zb_final, v_zm_zb_sum);
                __riscv_vector.vse32_v(v_zb_res, zb[k] + j * sizeof(real_t), vl);
            }
            #endif
            for (; j < jn - 1; ++j) {
                za[k][j] = ( zp[k+1][j-1] + zq[k+1][j-1] - zp[k][j-1] - zq[k][j-1] ) *
                           ( zr[k][j] + zr[k][j-1] ) / ( zm[k][j-1] + zm[k+1][j-1] );
                zb[k][j] = ( zp[k][j-1] + zq[k][j-1] - zp[k][j] - zq[k][j] ) *
                           ( zr[k][j] + zr[k-1][j] ) / ( zm[k][j] + zm[k][j-1] );
            }
        }

        // Second loop: Compute zu and zv
        for (Index_type k = 1; k < kn - 1; ++k) {
            Index_type j = 1;
            #if defined(__riscv_vector)
            size_t vlen_max_2 = __riscv_vector.maximum_vector_length;
            for (; j <= jn - 1 - (Index_type)vlen_max_2; j += (Index_type)vlen_max_2) {
                size_t vl = vlen_max_2;
                vfloat32m1_t v_za_j    = __riscv_vector.vle32_v(za[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_za_jm1   = __riscv_vector.vle32_v(za[k] + (j-1) * sizeof(real_t), vl);
                vfloat32m1_t v_zb_j     = __riscv_vector.vle32_v(zb[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zb_k1_j  = __riscv_vector.vle32_v(zb[k+1] + j * sizeof(real_t), vl);

                vfloat32m1_t v_zz_j     = __riscv_vector.vle32_v(zz[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zz_jp1   = __riscv_vector.vle32_v(zz[k] + (j+1) * sizeof(real_t), vl);
                vfloat32m1_t v_zz_jm1   = __riscv_vector.vle32_v(zz[k] + (j-1) * sizeof(real_t), vl);
                vfloat32m1_t v_zz_k1_j  = __riscv_vector.vle32_v(zz[k-1] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zz_k1_jp1 = __riscv_vector.vle32_v(zz[k+1] + j * sizeof(real_t), vl);

                vfloat32m1_t v_diff_jp1 = __riscv_vector.vfsub_vv(v_zz_j, v_zz_jp1);
                vfloat32m1_t v_diff_jm1 = __riscv_vector.vfsub_vv(v_zz_j, v_zz_jm1);
                vfloat32m1_t v_diff_k1  = __riscv_vector.vfsub_vv(v_zz_j, v_zz_k1_j);
                vfloat32m1_t v_diff_k1p1 = __riscv_vector.vfsub_vv(v_zz_j, v_zz_k1_jp1);

                vfloat32m1_t v_zu_term1 = __riscv_vector.vfmul_vv(v_za_j, v_diff_jp1);
                vfloat32m1_t v_zu_term2 = __riscv_vector.vfmul_vv(v_za_jm1, v_diff_jm1);
                vfloat32m1_t v_zu_term3 = __riscv_vector.vfmul_vv(v_zb_j, v_diff_k1);
                vfloat32m1_t v_zu_term4 = __riscv_vector.vfmul_vv(v_zb_k1_j, v_diff_k1p1);

                vfloat32m1_t v_zu_sum = __riscv_vector.vfadd_vv(v_zu_term1, v_zu_term2);
                v_zu_sum = __riscv_vector.vfsub_vv(v_zu_sum, v_zu_term3);
                v_zu_sum = __riscv_vector.vfsub_vv(v_zu_sum, v_zu_term4);

                vfloat32m1_t v_zu_final = __riscv_vector.vfmul_vv(v_zu_sum, (__riscv_vector.vfmv_vx_f32m1(s)));
                vfloat32m1_t v_zu_old   = __riscv_vector.vle32_v(zu[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zu_new    = __riscv_vector.vfadd_vv(v_zu_old, v_zu_final);
                __riscv_vector.vse32_v(v_zu_new, zu[k] + j * sizeof(real_t), vl);

                vfloat32m1_t v_zr_j     = __riscv_vector.vle32_v(zr[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zr_jp1   = __riscv_vector.vle32_v(zr[k] + (j+1) * sizeof(real_t), vl);
                vfloat32m1_t v_zr_jm1   = __riscv_vector.vle32_v(zr[k] + (j-1) * sizeof(real_t), vl);
                vfloat32m1_t v_zr_k1_j  = __riscv_vector.vle32_v(zr[k-1] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zr_k1_jp1 = __riscv_vector.vle32_v(zr[k+1] + j * sizeof(real_t), vl);

                vfloat32m1_t v_zr_diff_jp1 = __riscv_vector.vfsub_vv(v_zr_j, v_zr_jp1);
                vfloat32m1_t v_zr_diff_jm1 = __riscv_vector.vfsub_vv(v_zr_j, v_zr_jm1);
                vfloat32m1_t v_zr_diff_k1  = __riscv_vector.vfsub_vv(v_zr_j, v_zr_k1_j);
                vfloat32m1_t v_zr_diff_k1p1 = __riscv_vector.vfsub_vv(v_zr_j, v_zr_k1_jp1);

                vfloat32m1_t v_zv_term1 = __riscv_vector.vfmul_vv(v_za_j, v_zr_diff_jp1);
                vfloat32m1_t v_zv_term2 = __riscv_vector.vfmul_vv(v_za_jm1, v_zr_diff_jm1);
                vfloat32m1_t v_zv_term3 = __riscv_vector.vfmul_vv(v_zb_j, v_zr_diff_k1);
                vfloat32m1_t v_zv_term4 = __riscv_vector.vfmul_vv(v_zb_k1_j, v_zr_diff_k1p1);

                vfloat32m1_t v_zv_sum = __riscv_vector.vfadd_vv(v_zv_term1, v_zv_term2);
                v_zv_sum = __riscv_vector.vfsub_vv(v_zv_sum, v_zv_term3);
                v_zv_sum = __riscv_vector.vfsub_vv(v_zv_sum, v_zv_term4);

                vfloat32m1_t v_zv_final = __riscv_vector.vfmul_vv(v_zv_sum, (__riscv_vector.vfmv_vx_f32m1(s)));
                vfloat32m1_t v_zv_old   = __riscv_vector.vle32_v(zv[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zv_new    = __riscv_vector.vfadd_vv(v_zv_old, v_zv_final);
                __riscv_vector.vse32_v(v_zv_new, zv[k] + j * sizeof(real_t), vl);
            }
            #endif
            for (; j < jn - 1; ++j) {
                zu[k][j] += s*( za[k][j]   * ( zz[k][j] - zz[k][j+1] ) -
                                za[k][j-1] * ( zz[k][j] - zz[k][j-1] ) -
                                zb[k][j]   * ( zz[k][j] - zz[k-1][j] ) +
                                zb[k+1][j] * ( zz[k][j] - zz[k+1][j] ) );
                zv[k][j] += s*( za[k][j]   * ( zr[k][j] - zr[k][j+1] ) -
                                za[k][j-1] * ( zr[k][j] - zr[k][j-1] ) -
                                zb[k][j]   * ( zr[k][j] - zr[k-1][j] ) +
                                zb[k+1][j] * ( zr[k][j] - zr[k+1][j] ) );
            }
        }

        // Third loop: Compute zrout and zzout
        for (Index_type k = 1; k < kn - 1; ++k) {
            Index_type j = 1;
            #if defined(__riscv_vector)
            size_t vlen_max_3 = __riscv_vector.maximum_vector_length;
            for (; j <= jn - 1 - (Index_type)vlen_max_3; j += (Index_type)vlen_max_3) {
                size_t vl = vlen_max_3;
                vfloat32m1_t v_zr_k_j = __riscv_vector.vle32_v(zr[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zu_k_j = __riscv_vector.vle32_v(zu[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zr_res = __riscv_vector.vfmul_vv(v_zu_k_j, (__riscv_vector.vfmv_vx_f32m1(t)));
                vfloat32m1_t v_zr_out = __riscv_vector.vfadd_vv(v_zr_k_j, v_zr_res);
                __riscv_vector.vse32_v(v_zr_out, zrout[k] + j * sizeof(real_t), vl);

                vfloat32m1_t v_zz_k_j = __riscv_vector.vle32_v(zz[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zv_k_j = __riscv_vector.vle32_v(zv[k] + j * sizeof(real_t), vl);
                vfloat32m1_t v_zv_res = __riscv_vector.vfmul_vv(v_zv_k_j, (__riscv_vector.vfmv_vx_f32m1(t)));
                vfloat32m1_t v_zz_out = __riscv_vector.vfadd_vv(v_zz_k_j, v_zv_res);
                __riscv_vector.vse32_v(v_zz_out, zzout[k] + j * sizeof(real_t), vl);
            }
            #endif
            for (; j < jn - 1; ++j) {
                zrout[k][j] = zr[k][j] + t*zu[k][j];
                zzout[k][j] = zz[k][j] + t*zv[k][j];
            }
        }
        dummy(NULL, NULL, NULL, NULL, NULL, t);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_int_predict(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type offset = LEN_1D;
    real_t dm22 = 0.7, dm23 = 0.6, dm24 = 0.5, dm25 = 0.4;
    real_t dm26 = 0.3, dm27 = 0.2, dm28 = 0.1, c0 = 1.0/3.0;

    for (int nl = 0; nl < iterations; nl++) {
        #if defined(__riscv_vector)
        size_t vl;
        for (Index_type i = 0; i < LEN_1D; i += vl) {
            vl = __riscv_vsetvl_e32m1(LEN_1D - i);

            vfloat32m1_t v_p2  = __riscv_vle32_v_f32m1(px + i + offset * 2, vl);
            vfloat32m1_t v_p4  = __riscv_vle32_v_f32m1(px + i + offset * 4, vl);
            vfloat32m1_t v_p5  = __riscv_vle32_v_f32m1(px + i + offset * 5, vl);
            vfloat32m1_t v_p6  = __riscv_vle32_v_f32m1(px + i + offset * 6, vl);
            vfloat32m1_t v_p7  = __riscv_vle32_v_f32m1(px + i + offset * 7, vl);
            vfloat32m1_t v_p8  = __riscv_vle32_v_f32m1(px + i + offset * 8, vl);
            vfloat32m1_t v_p9  = __riscv_vle32_v_f32m1(px + i + offset * 9, vl);
            vfloat32m1_t v_p10 = __riscv_vle32_v_f32m1(px + i + offset * 10, vl);
            vfloat32m1_t v_p11 = __riscv_vle32_v_f32m1(px + i + offset * 11, vl);
            vfloat32m1_t v_p12 = __riscv_vle32_v_f32m1(px + i + offset * 12, vl);

            vfloat32m1_t v_c0  = __riscv_vfmv_v_f_f32m1(c0, vl);
            vfloat32m1_t v_dm22 = __riscv_vfmv_v_f_f32m1(dm22, vl);
            vfloat32m1_t v_dm23 = __riscv_vfmv_v_f_f32m1(dm23, vl);
            vfloat32m1_t v_dm24 = __riscv_vfmv_v_f_f32m1(dm24, vl);
            vfloat32m1_t v_dm25 = __riscv_vfmv_v_f_f32m1(dm25, vl);
            vfloat32m1_t v_dm26 = __riscv_vfmv_v_f_f32m1(dm26, vl);
            vfloat32m1_t v_dm27 = __riscv_vfmv_v_f_f32m1(dm27, vl);
            vfloat32m1_t v_dm28 = __riscv_vfmv_v_f_f32m1(dm28, vl);
            vfloat32m1_t v_zero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
            vfloat32m1_t v_one  = __riscv_vfmv_v_f_f32m1(1.0f, vl);

            // v_sum45 = c0 * (v_p4 + v_p5)
            vfloat32m1_t v_sum45 = __riscv_vfmadd_vv_f32m1(v_p4, v_p5, v_c0);

            // v_res = dm28*v_p12 + dm27*v_p11 + dm26*v_p10 + dm25*v_p9 + dm24*v_p8 + dm23*v_p7 + dm22*v_p6
            vfloat32m1_t v_res = __riscv_vfmadd_vv_f32m1(v_dm28, v_p12, v_zero);
            v_res = __riscv_vfmadd_vv_f32m1(v_dm27, v_p11, v_res);
            v_res = __riscv_vfmadd_vv_f32m1(v_dm26, v_p10, v_res);
            v_res = __riscv_vfmadd_vv_f32m1(v_dm25, v_p9, v_res);
            v_res = __riscv_vfmadd_vv_f32m1(v_dm24, v_p8, v_res);
            v_res = __riscv_vfmadd_vv_f32m1(v_dm23, v_p7, v_res);
            v_res = __riscv_vfmadd_vv_f32m1(v_dm22, v_p6, v_res);

            // v_res = v_res + v_sum45 + v_p2
            v_res = __riscv_vfmadd_vv_f32m1(v_sum45, v_one, v_res);
